import{j as e,c as n,L as r}from"./styles-DBbnN1LL.js";import{R as a}from"./ui-Ch9Yo4Ha.js";const i=[["What we collect","When you book a ticket, reserve a booth, or send an enquiry, we collect the details you provide: name, email address, phone number, city, and — for exhibitors — company details. The ticket-holder and exhibitor portals store your booking references so you can manage your participation."],["How we use it","We use your details to process bookings and reservations, send tickets and confirmations, share event updates you asked for, and operate the portals. We do not sell your personal data. With your consent, we may share relevant exhibitor or sponsor communications related to the event."],["Cookies and local storage","The site remembers your theme preference and portal sessions in your browser’s local storage. We do not use third-party advertising trackers. Basic, anonymised analytics may be used to improve the site."],["Data retention","Booking and enquiry records are kept for as long as needed to run the event and meet legal obligations, then removed or anonymised. You can ask us to delete your data at any time."],["Your rights","You can request a copy of the data we hold about you, ask us to correct it, or ask us to delete it. Contact info@profxmedia.com and we will respond within a reasonable time."],["Security","We take reasonable technical and organisational measures to protect your information. No method of transmission over the internet is completely secure, so we cannot guarantee absolute security."],["Children","The event and this site are intended for adults. We do not knowingly collect data from children."],["Changes","We may update this policy as the event approaches. Material changes will be highlighted on this page."]];function c(){return e.jsxs("main",{children:[e.jsx("section",{className:"page-hero",children:e.jsxs("div",{className:"container",children:[e.jsx(a,{className:"eyebrow",children:"Legal"}),e.jsxs(a,{as:"h1",children:["Privacy ",e.jsx("span",{className:"grad",children:"Policy."})]}),e.jsx(a,{className:"section-lead",children:"How Trading Expo Africa collects, uses and protects your information. Organised by ProFX Media FZ-LLC."})]})}),e.jsx("section",{className:"section",children:e.jsxs("div",{className:"container narrow",children:[e.jsx(a,{as:"p",className:"fine",children:"Last updated: October 2026"}),i.map(([o,t],s)=>e.jsxs(a,{className:"legal-block",children:[e.jsx("h2",{children:o}),e.jsx("p",{children:t})]},s)),e.jsx(a,{className:"center",style:{marginTop:32},children:e.jsx("a",{href:"contact.html",className:"btn btn-ghost",children:"Contact Us About Privacy"})})]})})]})}n(document.getElementById("root")).render(e.jsx(r,{page:"legal",children:e.jsx(c,{})}));
